using Microsoft.Extensions.DependencyInjection;

using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;

namespace G4.Services.Domain.V4.Mcp
{
    /// <summary>
    /// Declares the attribute tool types served by the G4 MCP server and derives their client definitions.
    /// </summary>
    /// <remarks>
    /// The server registration and the G4 tool catalog both read <see cref="Types"/>, so the definitions returned by
    /// g4.FindTool and g4.FindTools are generated by the same SDK schema builder that answers tools/list.
    /// </remarks>
    public static class McpToolTypes
    {
        #region *** Properties   ***

        /// <summary>
        /// Gets the attribute tool types registered with the MCP server.
        /// </summary>
        public static IReadOnlyList<Type> Types { get; } =
            [typeof(G4SystemTools), typeof(RecordingTools), typeof(FlowTools)];

        #endregion

        #region *** Methods      ***

        /// <summary>
        /// Builds the client-facing definition of every attribute tool declared by <see cref="Types"/>.
        /// </summary>
        /// <remarks>
        /// Building a definition never instantiates its tool type; the target factory runs only when the SDK
        /// invokes a tool, which the catalog never does.
        /// </remarks>
        /// <returns>The MCP tool definitions, ordered by tool name.</returns>
        public static Tool[] NewDefinitions()
        {
            // Select the public instance methods the SDK discovers through the tool attribute.
            var methods = Types
                .SelectMany(type => type.GetMethods(BindingFlags.Instance | BindingFlags.Public))
                .Where(method => method.GetCustomAttribute<McpServerToolAttribute>() is not null);

            // Generate each definition with the SDK defaults that the server registration also applies.
            return methods
                .Select(method => McpServerTool.Create(method, createTargetFunc: NewTarget(method), options: null))
                .Select(tool => tool.ProtocolTool)
                .OrderBy(tool => tool.Name, StringComparer.Ordinal)
                .ToArray();

            // Creates the declaring tool instance from request services, exactly as the SDK registration does.
            static Func<RequestContext<CallToolRequestParams>, object> NewTarget(MethodInfo method)
            {
                // Resolve constructor dependencies per request so the target follows the container lifetimes.
                return context => ActivatorUtilities.CreateInstance(context.Services, method.DeclaringType);
            }
        }

        #endregion
    }
}
